actions.script:
import groovy.json.JsonOutput

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_THREAT_SCENARIO_RISK',
                 startTime: ec.user.nowTimestamp, parameters: JsonOutput.toJson([graphVertexId: graphVertexId]),
                 hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    // ISO/DIS 24882 Table 5 sub-scores: sum the 5 analyst-assigned numericValues.
    List subScoreDefIds = ['CyberElapsedTimeParam', 'CyberSpecialistExpertiseParam',
            'CyberKnowledgeOfSoIParam', 'CyberWindowOfOpportunityParam', 'CyberEquipmentParam']
    BigDecimal sum = 0G
    subScoreDefIds.each { defId ->
        def p = ec.entity.find('moqui.math.Parameter')
                .condition('graphVertexId', graphVertexId).condition('parameterDefId', defId).one()
        if (p?.numericValue != null) sum = sum + p.numericValue
    }
    likelihoodSum = sum

    // Table 10: 0-13 High, 14-19 Medium, 20-24 Low, >=25 Very Low.
    if (sum <= 13) likelihoodRating = 'ClkHigh'
    else if (sum <= 19) likelihoodRating = 'ClkMedium'
    else if (sum <= 24) likelihoodRating = 'ClkLow'
    else likelihoodRating = 'ClkVeryLow'

    // Max Overall Impact across every linked DamageScenario.
    List impactOrder = ['CilNegligible', 'CilModerate', 'CilMajor', 'CilSevere']
    List edges = ec.entity.find('moqui.math.GraphEdge')
            .condition('fromVertexId', graphVertexId).condition('label', 'REALIZES_DAMAGE_SCENARIO')
            .list()
    impactOverall = 'CilNegligible'
    edges.each { edge ->
        def impactParam = ec.entity.find('moqui.math.Parameter')
                .condition('graphVertexId', edge.toVertexId).condition('parameterDefId', 'CyberImpactOverallParam').one()
        String candidate = impactParam?.parameterEnumId as String
        if (candidate && impactOrder.indexOf(candidate) > impactOrder.indexOf(impactOverall)) impactOverall = candidate
    }

    // Table 11: Impact (rows) x Likelihood (cols) -> Risk Rating 1-5.
    Map riskMatrix = [
        CilSevere:     [ClkVeryLow: 1, ClkLow: 3, ClkMedium: 4, ClkHigh: 5],
        CilMajor:      [ClkVeryLow: 1, ClkLow: 2, ClkMedium: 3, ClkHigh: 4],
        CilModerate:   [ClkVeryLow: 1, ClkLow: 2, ClkMedium: 2, ClkHigh: 3],
        CilNegligible: [ClkVeryLow: 1, ClkLow: 1, ClkMedium: 1, ClkHigh: 1]
    ]
    riskRating = riskMatrix[impactOverall][likelihoodRating]

    // Write results back onto the vertex (create-or-update, safe to re-run).
    Map<String, Object> resultParams = [
        CyberLikelihoodSumParam:    [numericValue: likelihoodSum],
        CyberLikelihoodRatingParam: [parameterEnumId: likelihoodRating],
        CyberRiskRatingParam:       [numericValue: riskRating]
    ]
    resultParams.each { defId, fields ->
        def existing = ec.entity.find('moqui.math.Parameter').useCache(false)
                .condition('graphVertexId', graphVertexId).condition('parameterDefId', defId).one()
        if (existing) {
            existing.setAll(fields)
            existing.update()
        } else {
            def newParam = ec.entity.makeValue('moqui.math.Parameter')
                    .setAll([parameterDefId: defId, graphVertexId: graphVertexId] + fields)
            newParam.setSequencedIdPrimary()
            newParam.create()
        }
    }

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(
                    [graphVertexId: graphVertexId, likelihoodSum: likelihoodSum,
                     likelihoodRating: likelihoodRating, impactOverall: impactOverall, riskRating: riskRating])])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}
